mapper.select:
SELECT COUNT(*)
FROM PRODUCT
WHERE SELLER_NO = #{sellerNo}
  AND DISPLAY_YN = #{displayYn}

  AND SALE_STATUS = #{saleStatus}

SELECT PO.OPTION_ID, PO.PRODUCT_NO, P.PRODUCT_NAME, PO.OPTION1_VALUE, PO.OPTION2_VALUE, PO.OPTION3_VALUE, NVL(PO.PRICE, 0) AS PRICE, PO.NORMAL_PRICE, PO.QUANTITY, PO.STATUS, IMG.IMAGE_URL AS THUMBNAIL_URL FROM PRODUCT_OPTION PO JOIN PRODUCT P ON PO.PRODUCT_NO = P.PRODUCT_NO LEFT JOIN ( SELECT PRODUCT_NO, IMAGE_URL, ROW_NUMBER() OVER (PARTITION BY PRODUCT_NO ORDER BY OPTION_ID, IMAGE_ORDER) AS RN FROM PRODUCT_IMAGE WHERE IMAGE_PURPOSE = '대표' ) IMG ON IMG.PRODUCT_NO = P.PRODUCT_NO AND IMG.RN = 1 WHERE P.SELLER_NO = #{sellerNo}
AND P.PRODUCT_NO = #{productNo}
ORDER BY P.CREATED_DATE DESC, P.PRODUCT_NO DESC, PO.OPTION_ID

mapper.update:
UPDATE PRODUCT
SET DISPLAY_YN = #{displayYn},
    UPDATED_DATE = SYSDATE
WHERE PRODUCT_NO = #{productNo}
  AND SELLER_NO = #{sellerNo}

UPDATE PRODUCT
SET SALE_STATUS = #{saleStatus},
    UPDATED_DATE = SYSDATE
WHERE PRODUCT_NO = #{productNo}
  AND SELLER_NO = #{sellerNo}
  AND SALE_STATUS IN ('판매 중', '판매 중지')

UPDATE PRODUCT_OPTION
SET PRICE = #{price},
    NORMAL_PRICE = #{normalPrice, jdbcType=NUMERIC},
    QUANTITY = #{quantity},
    STATUS = #{status}
WHERE OPTION_ID = #{optionId}
  AND EXISTS (
        SELECT 1 FROM PRODUCT P
        WHERE P.PRODUCT_NO = PRODUCT_OPTION.PRODUCT_NO
          AND P.SELLER_NO = #{sellerNo}
  )

mapper.insert:
INSERT INTO PRODUCT_IMAGE (
    image_no, product_no, OPTION_ID, image_purpose, image_order, image_url, created_date
) VALUES (
    SEQ_PRODUCT_IMAGE.NEXTVAL, #{productNo}, #{optionId, jdbcType=NUMERIC},
    #{purpose}, #{imageOrder}, #{imageUrl}, SYSDATE
)
